True from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    outside = [[False] * w for _ in range(h)]
    q = deque()
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == 0 and not outside[r][c]:
                outside[r][c] = True
                q.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == 0 and not outside[r][c]:
                outside[r][c] = True
                q.append((r, c))
    while q:
        r, c = q.popleft()
        for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0 and not outside[nr][nc]:
                outside[nr][nc] = True
                q.append((nr, nc))
    return [[8 if grid[r][c] == 0 and not outside[r][c] else grid[r][c] for c in range(w)] for r in range(h)]
